database_schema:
CREATE TABLE delta.sales_data (
  transaction_id STRING,
  customer_id STRING,
  amount DOUBLE,
  transaction_date TIMESTAMP
) USING DELTA LOCATION 's3://lakehouse/sales_data' TBLPROPERTIES ('delta.enableChangeDataFeed'='true');

ALTER TABLE delta.sales_data SET TBLPROPERTIES ('delta.retentionDuration'='30 days');

CREATE TABLE delta.customer_profiles (
  customer_id STRING,
  name STRING,
  email STRING,
  last_updated TIMESTAMP
) USING DELTA LOCATION 's3://lakehouse/customer_profiles';
